function escapeMarkup(value) {
  return String(value ?? '').replace(/[&<>"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[char]));
}

function escapeDataAttr(value) {
  return escapeMarkup(value).replace(/'/g, '&#39;');
}

