function notePhotoSrc(file) {
  if (!file) return '';
  if (window.SUAS_NOTES && window.SUAS_NOTES[file]) return window.SUAS_NOTES[file];
  return `assets/notes/${file}`;
}

function scentFamilyGroup(note) {
  const style = scentNoteProfile(note).style;
  if (style === 'fruit' || style === 'citrus') return 'fruit';
  if (style === 'floral') return 'floral';
  if (style === 'cream' || style === 'resin' || style === 'bean') return 'gourmand';
  if (style === 'herbal' || style === 'wood') return 'green';
  return 'sparkle';
}

function formatPourMl(value) {
  const amount = Number(value);
  if (!Number.isFinite(amount)) return '';
  return `${Number.isInteger(amount) ? amount : amount.toFixed(1)} mL`;
}

function selfPourLabel(index) {
  const product = productChoices.find((item) => item.id === guideState.product) || productChoices[0];
  const plan = selfPourPlan(product.volume);
  const item = plan[index];
  if (!item) return '';
  if (plan.length === 1) return `${formatPourMl(item.ml)} / ALL`;
  if (index === 0) return `${formatPourMl(item.ml)} / MAIN`;
  return `${formatPourMl(item.ml)} / EXTRA`;
}

function scentNoteCard(note, selected, index) {
  const profile = scentNoteProfile(note);
  const safeNote = escapeMarkup(note);
  const slot = selected ? guideState.notes.indexOf(note) : -1;
  const pour = slot >= 0 ? selfPourLabel(slot) : '';
  return `<button class="scent-note-card scent-note-${profile.style} scent-visual-${profile.visual || profile.style}${selected ? ' is-selected' : ''}" data-note="${escapeDataAttr(note)}" ${pour ? `data-pour="${escapeDataAttr(pour)}"` : ''} type="button" aria-pressed="${selected}" style="--note-a:${profile.a};--note-b:${profile.b};--note-ink:${profile.ink};--note-index:${index}"><span class="scent-note-photo" aria-label="${safeNote} visual">${scentIngredientArt(profile, note)}</span><span class="scent-note-copy"><strong>${safeNote}</strong><small>${profile.family}</small><small>${profile.mood}</small></span></button>`;
}

function scentNoteMini(note, index) {
  const profile = scentNoteProfile(note);
  return `<span class="scent-polaroid scent-note-${profile.style} scent-visual-${profile.visual || profile.style}" style="--note-a:${profile.a};--note-b:${profile.b};--note-ink:${profile.ink};--note-index:${index}">${scentIngredientArt(profile, note)}<b>${escapeMarkup(note)}</b><small>${profile.family}</small></span>`;
}
