const oilBases = [
  { name: 'Glow Base', feel: 'balanced + luminous', loadPercent: 10, ingredients: ['Jojoba Oil', 'Sunflower Oil', 'Rice Bran Oil', 'Castor Oil', 'Fractionated Coconut Oil', 'Vitamin E Oil'] },
  { name: 'Silky Dry Oil Base', feel: 'light + quick-dry feel', loadPercent: 8, ingredients: ['Jojoba Oil', 'Grapeseed Oil', 'Fractionated Coconut Oil', 'IPM', 'Vitamin E Oil'] },
  { name: 'Rich Sensitive Skin', feel: 'cushiony + deeply conditioned', loadPercent: 5, ingredients: ['Sunflower Oil', 'Jojoba Oil', 'Rice Bran Oil', 'Vitamin E Oil'] }
];
function noteLimit() {
  return guideState.labMode === 'self' ? SELF_NOTE_MAX : 4;
}
function normalizeOilBase(name) {
  const raw = String(name || '');
  if (/rich/i.test(raw)) return 'Rich Sensitive Skin';
  if (/silk|dry/i.test(raw)) return 'Silky Dry Oil Base';
  return 'Glow Base';
}
function oilLoadPercent(name) {
  const base = oilBases.find((item) => item.name === normalizeOilBase(name)) || oilBases[0];
  const saved = getGuidedSettings().formula.oilLoads || {};
  return Number(saved[base.name]) || base.loadPercent;
}
function selfPourPlan(volume = 30) {
  const scale = Number(volume || 30) / 30;
  const notes = (guideState.notes || []).slice(0, SELF_NOTE_MAX);
  if (!notes.length) return [];
  if (notes.length === 1) return [{ note: notes[0], ml: Number((30 * scale).toFixed(1)) }];
  if (notes.length === 2) return [
    { note: notes[0], ml: Number((20 * scale).toFixed(1)) },
    { note: notes[1], ml: Number((10 * scale).toFixed(1)) }
  ];
  return notes.map((note, index) => ({ note, ml: Number((SELF_POUR_ML[index] * scale).toFixed(1)) }));
}

