function packSrc(key) {
  if (window.SUAS_PACK_EMBED && window.SUAS_PACK_EMBED[key]) return window.SUAS_PACK_EMBED[key];
  if (window.SUAS_PACK && window.SUAS_PACK[key]) return window.SUAS_PACK[key];
  const local = location.hostname === '127.0.0.1' || location.hostname === 'localhost' || location.protocol === 'file:';
  if (local) return `assets/products/pack-${key}.jpg`;
  return PACK_FALLBACK[key];
}

function productFigure(kind) {
  const key = /butter/.test(kind) ? 'butter' : (/oil/.test(kind) && !/rollon/.test(kind)) ? 'oil' : 'perfume';
  const alt = key === 'oil' ? 'SUAS body oil bottle' : key === 'butter' ? 'SUAS butter creme jar' : 'SUAS perfume bottle';
  const src = packSrc(key);
  return `<img class="product-photo pack-${key}" src="${src}" alt="${alt}" width="168" height="168" decoding="async" loading="eager">`;
}

