  if (action === 'engraving-status') { const job = state.engravingJobs.find((item) => item.id === button.dataset.jobId); if (job) { job.status = button.dataset.status; job.updatedAt = queueNow(); queueEvent(state, `ENGRAVING ${job.status}`, job.customerId); } }
  if (action === 'clear-completed') { state.customers = state.customers.filter((item) => item.status !== 'COMPLETE' && item.status !== 'LEFT STORE'); queueEvent(state, 'COMPLETED FILES CLEARED'); }
  if (action === 'reset-day') { if (!confirm('Reset the full queue day? This clears queue customers, stations, engraving jobs, and event log.')) return; saveQueueState(queueDefaultState()); renderQueueModule(); return; }
  saveQueueState(state);
